183	    }
184	
185	    /* Start timer waiting for connect */
186	    alarm_set_on_mloop(p_bcb->conn_timer, BNEP_CONN_TIMEOUT_MS,
187	                       bnep_conn_timer_timeout, p_bcb);
188	  }
