1713	int bt_l2cap_br_chan_connect(struct bt_conn *conn, struct bt_l2cap_chan *chan,
1714				     uint16_t psm)
1715	{
1716		struct net_buf *buf;
1717		struct bt_l2cap_sig_hdr *hdr;
1718		struct bt_l2cap_conn_req *req;
1719		struct bt_l2cap_br_chan *br_chan = BR_CHAN(chan);
1720	
1721		if (!psm) {
1722			return -EINVAL;
1723		}
1724	
1725		if (br_chan->psm) {
1726			return -EEXIST;
1727		}
1728	
1729		/* PSM must be odd and lsb of upper byte must be 0 */
1730		if ((psm & 0x0101) != 0x0001) {
1731			return -EINVAL;
1732		}
1733	
1734		if (br_chan->required_sec_level > BT_SECURITY_L4) {
1735			return -EINVAL;
1736		} else if (br_chan->required_sec_level == BT_SECURITY_L0 &&
1737			   psm != L2CAP_BR_PSM_SDP) {
1738			br_chan->required_sec_level = BT_SECURITY_L1;
1739		}
1740	
1741		switch (br_chan->state) {
1742		case BT_L2CAP_CONNECTED:
1743			/* Already connected */
1744			return -EISCONN;
1745		case BT_L2CAP_DISCONNECTED:
1746			/* Can connect */
1747			break;
1748		case BT_L2CAP_CONFIG:
1749		case BT_L2CAP_DISCONNECTING:
1750		default:
1751			/* Bad context */
1752			return -EBUSY;
1753		}
1754	
1755		if (!l2cap_br_chan_add(conn, chan, l2cap_br_chan_destroy)) {
1756			return -ENOMEM;
1757		}
1758	
1759		br_chan->psm = psm;
1760		bt_l2cap_br_chan_set_state(chan, BT_L2CAP_CONNECTING);
1761		atomic_set_bit(BR_CHAN(chan)->flags, L2CAP_FLAG_CONN_PENDING);
1762	
1763		switch (l2cap_br_conn_security(chan, psm)) {
1764		case L2CAP_CONN_SECURITY_PENDING:
1765			/*
1766			 * Authentication was triggered, wait with sending request on
1767			 * connection security changed callback context.
1768			 */
1769			 return 0;
1770		case L2CAP_CONN_SECURITY_PASSED:
1771			break;
1772		case L2CAP_CONN_SECURITY_REJECT:
1773		default:
1774			l2cap_br_chan_cleanup(chan);
1775			return -EIO;
1776		}
1777	
1778		buf = bt_l2cap_create_pdu(&br_sig_pool, 0);
1779	
1780		hdr = net_buf_add(buf, sizeof(*hdr));
1781		hdr->code = BT_L2CAP_CONN_REQ;
1782		hdr->ident = l2cap_br_get_ident(conn->hdev);
1783		hdr->len = sys_cpu_to_le16(sizeof(*req));
1784	
1785		req = net_buf_add(buf, sizeof(*req));
1786		req->psm = sys_cpu_to_le16(psm);
1787		req->scid = sys_cpu_to_le16(BR_CHAN(chan)->rx.cid);
1788	
1789		l2cap_br_chan_send_req(BR_CHAN(chan), buf, L2CAP_BR_CONN_TIMEOUT);
1790	
1791		return 0;
1792	}
