156	bool bt_br_update_sec_level(struct bt_conn *conn)
157	{
158		if (!conn->encrypt) {
159			conn->sec_level = BT_SECURITY_L1;
160			return true;
161		}
162	
163		if (conn->br.link_key) {
164			if (conn->br.link_key->flags & BT_LINK_KEY_AUTHENTICATED) {
165				if (conn->encrypt == BT_HCI_ENCRYPTION_ON_BR_AES_CCM) {
166					conn->sec_level = BT_SECURITY_L4;
167				} else {
168					conn->sec_level = BT_SECURITY_L3;
169				}
170			} else {
171				conn->sec_level = BT_SECURITY_L2;
172			}
173		} else {
174			LOG_WRN("No BR/EDR link key found");
175			conn->sec_level = BT_SECURITY_L2;
176		}
177	
178		if (!br_sufficient_key_size(conn)) {
179			LOG_ERR("Encryption key size is not sufficient");
180			bt_conn_disconnect(conn, BT_HCI_ERR_AUTH_FAIL);
181			return false;
182		}
183	
184		if (conn->required_sec_level > conn->sec_level) {
185			LOG_ERR("Failed to set required security level");
186			bt_conn_disconnect(conn, BT_HCI_ERR_AUTH_FAIL);
187			return false;
188		}
189	
190		return true;
191	}
